<?php require_once __DIR__.'/includes/db.php'; $matches=$pdo->query("SELECT p.*, (SELECT MIN(harga) FROM kategori_tiket k WHERE k.pertandingan_id=p.id) harga_mulai FROM pertandingan p WHERE p.status='akan_datang' ORDER BY p.tanggal")->fetchAll(); ?>
<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Pertandingan | LagaKita</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="assets/css/style.css" rel="stylesheet"></head><body><?php include __DIR__.'/includes/navbar.php'; ?><main class="container py-5"><p class="eyebrow">JADWAL</p><h1 class="fw-bold mb-4">Semua pertandingan</h1><div class="row g-4"><?php foreach($matches as $m): ?><div class="col-md-6 col-lg-4"><article class="card match-card h-100"><div class="card-body p-4"><p class="small text-muted"><?= e(date('d M Y · H:i',strtotime($m['tanggal']))) ?> WIB · <?= e($m['stadion']) ?></p><h2 class="h5 fw-bold"><?= e($m['tim_tuan_rumah']) ?> <span class="text-muted">vs</span> <?= e($m['tim_tamu']) ?></h2><p class="text-muted"><?= e($m['kompetisi']) ?></p><strong><?= $m['harga_mulai']!==null?rupiah($m['harga_mulai']):'Tiket belum tersedia' ?></strong><a class="btn btn-outline-dark w-100 mt-3" href="detail.php?id=<?= (int)$m['id'] ?>">Pilih tiket</a></div></article></div><?php endforeach; ?><?php if(!$matches): ?><p>Jadwal belum tersedia.</p><?php endif; ?></div></main><?php include __DIR__.'/includes/footer.php'; ?></body></html>
